#[serde(tag = "_variant")]
pub enum RetentionAdmission {
    RetentionAdmitted,
    RetentionRefused {
        reason: RetentionRefusalReason,
    },
}
impl RetentionAdmission {
    pub fn reason(&self) -> RetentionRefusalReason {
        match self {
            RetentionAdmission::RetentionAdmitted => panic!("no reason on unit variant"),
            RetentionAdmission::RetentionRefused { reason: __val, .. } => __val.clone(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct RefusedProvider {
    pub provider_id: String,
    pub reason: RetentionRefusalReason,
}

pub fn retention_admission(r: Rc<ProviderRetention>) -> Rc<RetentionAdmission> {
    match (*r.release_policy.clone()).clone() {
    ReleasePolicy::ReleasedAtProviderScopeExit => Rc::new(RetentionAdmission::RetentionAdmitted),
    ReleasePolicy::ReleasedNever => capacity_admission(r.capacity.clone()),
    ReleasePolicy::ReleasedManually => capacity_admission(r.capacity.clone()),
    ReleasePolicy::ReleasedAfterInterval { after_write: _, .. } => capacity_admission(r.capacity.clone()),
    ReleasePolicy::ReleasedAfterIdle { idle: _, .. } => capacity_admission(r.capacity.clone()),
}
}

pub fn capacity_admission(c: Rc<CapacityPolicy>) -> Rc<RetentionAdmission> {
    match (*c.clone()).clone() {
    CapacityPolicy::CapacityUnbounded => Rc::new(RetentionAdmission::RetentionRefused {
    reason: RetentionRefusalReason::RetentionUnbounded,
}),
    CapacityPolicy::CapacityBounded { .. } => Rc::new(RetentionAdmission::RetentionAdmitted),
    CapacityPolicy::CapacityUnobserved => Rc::new(RetentionAdmission::RetentionRefused {
    reason: RetentionRefusalReason::RetentionUnobserved,
}),
}
}

pub fn retention_is_admitted(r: Rc<ProviderRetention>) -> bool {
    match (*retention_admission(r)).clone() {
    RetentionAdmission::RetentionAdmitted => true,
    RetentionAdmission::RetentionRefused { reason: _, .. } => false,
}
}

pub fn provider_refusals(ps: Rc<Vec<Rc<CacheProvider>>>) -> Rc<Vec<Rc<RefusedProvider>>> {
    Rc::new({ let mut __result = Vec::new(); for p in ps.iter().cloned() { __result.extend((*match (*retention_admission(p.retention.clone())).clone() {
    RetentionAdmission::RetentionAdmitted => Rc::new(vec![]),
    RetentionAdmission::RetentionRefused { reason: why, .. } => Rc::new(vec![Rc::new(RefusedProvider {
    provider_id: p.id.clone(),
    reason: why.clone(),
})]),
}).iter().cloned()); } __result })
}

pub fn retention_refusal_verdict(identity: String, lca: Rc<Vec<Rc<Frame>>>, refused: Rc<RefusedProvider>) -> Rc<LadderVerdict> {
    match refused.reason.clone() {
    RetentionRefusalReason::RetentionUnbounded => Rc::new(LadderVerdict::RefusedRetentionUnbounded {
    identity: identity.clone(),
    lca: lca.clone(),
    provider_id: refused.provider_id.clone(),
}),
    RetentionRefusalReason::RetentionUnobserved => Rc::new(LadderVerdict::RefusedRetentionUnobserved {
    identity: identity.clone(),
    lca: lca.clone(),
    provider_id: refused.provider_id.clone(),
}),
}
}

pub fn discharge_verdict(identity: String, lca: Rc<Vec<Rc<Frame>>>, providers: Rc<Vec<Rc<CacheProvider>>>) -> Rc<LadderVerdict> {
    {
        let content_covering = Rc::new({ let mut __result = Vec::new(); for p in providers.iter().cloned() { if (((provider_is_store_tier(p.clone()) && provider_covers_identity(p.clone(), identity.clone())) && crate::std_algebra::is_prefix_of(p.scope.clone(), lca.clone(), |a, b| frame_eq(a, b))) && provider_is_content_keyed(p.clone())) { __result.push(p); } } __result });
let admitted = Rc::new({ let mut __result = Vec::new(); for p in content_covering.iter().cloned() { if retention_is_admitted(p.retention.clone()) { __result.push(p); } } __result });
match admitted.clone().first().cloned() {
    Some(chosen) => Rc::new(LadderVerdict::Discharged {
    identity: identity.clone(),
    lca: lca.clone(),
    provider_id: chosen.id.clone(),
}),
    std::option::Option::None => match provider_refusals(content_covering.clone()).first().cloned() {
    Some(refused_one) => retention_refusal_verdict(identity.clone(), lca.clone(), refused_one.clone()),
    std::option::Option::None => {
            let scope_covering = Rc::new({ let mut __result = Vec::new(); for p in providers.iter().cloned() { if ((provider_is_store_tier(p.clone()) && provider_covers_identity(p.clone(), identity.clone())) && crate::std_algebra::is_prefix_of(p.scope.clone(), lca.clone(), |a, b| frame_eq(a, b))) { __result.push(p); } } __result });
match scope_covering.clone().first().cloned() {
    Some(existence_one) => Rc::new(LadderVerdict::RefusedExistenceKeyed {
    identity: identity.clone(),
    lca: lca.clone(),
    provider_id: existence_one.id.clone(),
}),
    std::option::Option::None => {
                let narrow = Rc::new({ let mut __result = Vec::new(); for p in providers.iter().cloned() { if (provider_is_store_tier(p.clone()) && provider_covers_identity(p.clone(), identity.clone())) { __result.push(p); } } __result });
match narrow.clone().first().cloned() {
    Some(narrow_one) => Rc::new(LadderVerdict::RefusedScopeTooNarrow {
    identity: identity.clone(),
    lca: lca.clone(),
    provider_id: narrow_one.id.clone(),
}),
    std::option::Option::None => Rc::new(LadderVerdict::RefusedNoProvider {
    identity: identity.clone(),
    lca: lca.clone(),
}),
}
},
}
},
},
}
}
}

pub fn group_redundant_verdict(identity: String, group: Rc<Vec<Rc<FrameDemand>>>, providers: Rc<Vec<Rc<CacheProvider>>>, cost_floor_exempt: Rc<Vec<String>>) -> Rc<LadderVerdict> {
    {
        let lca = group_obligation_lca(group.clone());
if frame_path_last_is_shared_state(lca.clone()) {
            Rc::new(LadderVerdict::AuthoredDuplication {
    identity: identity.clone(),
    lca: lca.clone(),
    site_count: (group.clone().len() as i64),
})
        } else {
            if string_list_contains(cost_floor_exempt, identity.clone()) {
                Rc::new(LadderVerdict::AcceptedBelowCostFloor {
    identity: identity.clone(),
})
            } else {
                discharge_verdict(identity.clone(), lca.clone(), providers)
            }
        }
}
}

pub fn group_verdict(identity: String, group: Rc<Vec<Rc<FrameDemand>>>, providers: Rc<Vec<Rc<CacheProvider>>>, cost_floor_exempt: Rc<Vec<String>>) -> Rc<LadderVerdict> {
    if group_has_nature_conflict(group.clone()) {
        Rc::new(LadderVerdict::RefusedNatureConflict {
    identity: identity.clone(),
})
    } else {
        match (*group_nature(group.clone())).clone() {
    DemandNature::FreshEffect => Rc::new(LadderVerdict::ExemptFreshEffect {
    identity: identity.clone(),
}),
    DemandNature::WorldRead { staleness_envelope_declared: declared, .. } => if !group_is_redundant(group.clone()) {
            Rc::new(LadderVerdict::AcceptedSingleRecompute {
    identity: identity.clone(),
})
        } else {
            if declared.clone() {
                group_redundant_verdict(identity.clone(), group.clone(), providers.clone(), cost_floor_exempt.clone())
            } else {
                Rc::new(LadderVerdict::RefusedUnmodeledWorldRead {
    identity: identity.clone(),
    lca: group_obligation_lca(group.clone()),
})
            }
        },
    DemandNature::PureComputation => if group_is_redundant(group.clone()) {
            group_redundant_verdict(identity.clone(), group.clone(), providers.clone(), cost_floor_exempt.clone())
        } else {
            Rc::new(LadderVerdict::AcceptedSingleRecompute {
    identity: identity.clone(),
})
        },
    DemandNature::IdempotentEffect => if group_is_redundant(group.clone()) {
            group_redundant_verdict(identity.clone(), group.clone(), providers.clone(), cost_floor_exempt.clone())
        } else {
            Rc::new(LadderVerdict::AcceptedSingleRecompute {
    identity: identity.clone(),
})
        },
}
    }
}

pub fn materialization_ladder(demands: Rc<Vec<Rc<FrameDemand>>>, providers: Rc<Vec<Rc<CacheProvider>>>, cost_floor_exempt: Rc<Vec<String>>) -> Rc<Vec<Rc<LadderVerdict>>> {
    Rc::new({ let mut __result = Vec::new(); for identity in ladder_distinct_identities(demands.clone()).iter().cloned() { __result.push(group_verdict(identity.clone(), ladder_group(demands.clone(), identity.clone()), providers.clone(), cost_floor_exempt.clone())); } __result })
}

pub fn ladder_verdict_is_green(v: Rc<LadderVerdict>) -> bool {
    match (*v.clone()).clone() {
    LadderVerdict::RefusedNatureConflict { identity: _, .. } => false,
    LadderVerdict::AuthoredDuplication { .. } => false,
    LadderVerdict::DeadComputation { identity: _, .. } => false,
    LadderVerdict::AcceptedEffectIsTheUse { identity: _, .. } => true,
    LadderVerdict::Discharged { .. } => true,
    LadderVerdict::RefusedNoProvider { .. } => false,
    LadderVerdict::RefusedScopeTooNarrow { .. } => false,
    LadderVerdict::RefusedExistenceKeyed { .. } => false,
    LadderVerdict::RefusedRetentionUnbounded { .. } => false,
    LadderVerdict::RefusedRetentionUnobserved { .. } => false,
    LadderVerdict::RefusedUnmodeledWorldRead { .. } => false,
    LadderVerdict::ExemptFreshEffect { identity: _, .. } => true,
    LadderVerdict::AcceptedBelowCostFloor { identity: _, .. } => true,
    LadderVerdict::AcceptedSingleRecompute { identity: _, .. } => true,
}
}

pub fn ladder_verdict_prescribes(v: Rc<LadderVerdict>) -> Materialization {
    match (*v.clone()).clone() {
    LadderVerdict::RefusedNatureConflict { identity: _, .. } => Materialization::Recompute,
    LadderVerdict::AuthoredDuplication { .. } => Materialization::Share,
    LadderVerdict::DeadComputation { identity: _, .. } => Materialization::Recompute,
    LadderVerdict::AcceptedEffectIsTheUse { identity: _, .. } => Materialization::Recompute,
    LadderVerdict::Discharged { .. } => Materialization::Memoize,
    LadderVerdict::RefusedNoProvider { .. } => Materialization::Memoize,
    LadderVerdict::RefusedScopeTooNarrow { .. } => Materialization::Memoize,
    LadderVerdict::RefusedExistenceKeyed { .. } => Materialization::Memoize,
    LadderVerdict::RefusedRetentionUnbounded { .. } => Materialization::Memoize,
    LadderVerdict::RefusedRetentionUnobserved { .. } => Materialization::Memoize,
    LadderVerdict::RefusedUnmodeledWorldRead { .. } => Materialization::Recompute,
    LadderVerdict::ExemptFreshEffect { identity: _, .. } => Materialization::Recompute,
    LadderVerdict::AcceptedBelowCostFloor { identity: _, .. } => Materialization::Recompute,
    LadderVerdict::AcceptedSingleRecompute { identity: _, .. } => Materialization::Recompute,
}
}

